import { Check, Copy } from "lucide-react"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { ask } from "./confirm.tsx"
import { t } from "./i18n.ts"
import { toast } from "./toast.tsx"

/** Copies text, and says so. */
export async function copy(text: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text)
  } catch {
    // Without the clipboard's API (or its permission): a selection, copied.
    const area = document.createElement("textarea")
    area.value = text
    area.style.position = "fixed"
    area.style.opacity = "0"
    document.body.append(area)
    area.select()
    document.execCommand("copy")
    area.remove()
  }
  toast(t("copied"))
}

/**
 * Copies an image, by its address, as an image (to paste into WhatsApp), and
 * says so: as PNG, the one type browsers put on the clipboard, drawn on a
 * canvas when it is not one. A browser that cannot copy it offers to download
 * it instead. It answers false when the person chose neither.
 */
export async function copyImage(url: string): Promise<boolean> {
  // Fetched once, for the clipboard or the download.
  const blob = fetch(url).then((res) => {
    if (!res.ok) throw new Error(`${res.status} ${url}`)
    return res.blob()
  })
  blob.catch(() => {})
  if (canCopyImages()) {
    try {
      // The clipboard is written at once, with what it will hold to come:
      // Safari only lets it be written in the click's own turn.
      await navigator.clipboard.write([new ClipboardItem({ "image/png": blob.then(png) })])
      toast(t("imageCopied"))
      return true
    } catch {
      // Below: a download.
    }
  }
  if (!(await ask(t("imageNotCopied"), { confirm: t("download") }))) return false
  download(await blob.catch(() => null), url)
  return true
}

/** Whether the browser puts images on the clipboard. */
export function canCopyImages(): boolean {
  return typeof ClipboardItem !== "undefined" && typeof navigator !== "undefined" && typeof navigator.clipboard?.write === "function"
}

/** An image as PNG: itself, or drawn on a canvas. */
async function png(image: Blob): Promise<Blob> {
  if (image.type === "image/png") return image
  const bitmap = await createImageBitmap(image)
  const canvas = document.createElement("canvas")
  canvas.width = bitmap.width
  canvas.height = bitmap.height
  canvas.getContext("2d")!.drawImage(bitmap, 0, 0)
  bitmap.close()
  return new Promise((done, fail) => canvas.toBlob((b) => (b ? done(b) : fail(new Error("png"))), "image/png"))
}

/** Downloads an image: what was fetched, or its address, opened. */
function download(blob: Blob | null, url: string): void {
  const a = document.createElement("a")
  a.href = blob ? URL.createObjectURL(blob) : url
  a.download = fileName(url)
  a.target = "_blank"
  a.rel = "noopener"
  document.body.append(a)
  a.click()
  a.remove()
  if (blob) setTimeout(() => URL.revokeObjectURL(a.href), 1000)
}

/** The name of a downloaded image: the last part of its address' path. */
export function fileName(url: string): string {
  try {
    const name = new URL(url, "http://x").pathname.split("/").filter(Boolean).pop()
    return name ? decodeURIComponent(name) : "image"
  } catch {
    return "image"
  }
}

/** A small button that copies text, showing a check for a moment. */
export function CopyButton({ text, label, className }: { text: string; label?: string; className?: string }) {
  const [done, setDone] = useState(false)
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-xs"
      className={cn("text-muted-foreground", className)}
      aria-label={label ?? t("copy")}
      onClick={async (e) => {
        e.stopPropagation()
        await copy(text)
        setDone(true)
        setTimeout(() => setDone(false), 1500)
      }}
    >
      {done ? <Check /> : <Copy />}
    </Button>
  )
}
